{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "The closest analogue PF-4181366, sharing the same bicyclic lactam core and piperidine-methyl linker, showed excellent central exposure in rats with a brain/plasma ratio of 1.4, free brain exposure equal to CSF, and no P-gp liability, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A related compound with the same core and a tetrahydropyran substituent achieved Kpuu,brain of 0.47 and Kpuu,CSF of 0.76 in rats, demonstrating good brain and CSF penetration despite moderate polarity and supporting the query's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A structurally related CNS-active compound partitioned rapidly into rat brain with brain/plasma ratios greater than 1 after subcutaneous dosing, confirming that this chemotype can achieve meaningful brain exposure in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "PET imaging in rats showed brain accumulation of a close mGluR2 ligand from the same scaffold family, providing direct in vivo evidence of BBB permeability for this chemical series.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of PF-4181366 (C11), which showed excellent rat brain penetration, free brain exposure equal to CSF, and no P-gp liability; additional close analogues with the same core and even a tetrahydropyran substituent showed good Kpuu,brain/CSF. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement exists for the exact query molecule.",
    "The exact efflux-transporter profile of the query has not been experimentally determined, although the closest analogue showed no P-gp liability.",
    "Minor structural differences from PF-4181366 (pyrimidine vs quinazoline and tetrahydropyran vs cyclopentyl) could alter disposition, but the available close analogues support the same direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

